// 事件：y 年（公元），mo 月，ll [经度, 纬度]，k war|pol|dip|eco|cul，refs 出处，who 参与人物
const EVENTS = [
  { y: 69, mo: 8, t: '巴达维人起义', p: '维泰拉营地', m: '今德国北莱茵-威斯特法伦州克桑滕', ll: [6.46, 51.66], k: 'war', refs: ['塔西佗·历史'],
    d: '莱茵河口的巴达维人世代为罗马提供最精锐的辅助骑兵，却不纳贡赋。四帝之年里，维特利乌斯的征兵官强征巴达维的少年老弱，激起民愤。统领巴达维部队二十五年的王族尤利乌斯·奇维利斯借口支持韦斯巴芗起兵，联合莱茵河东岸的日耳曼诸部，围攻下游的维泰拉营地。布鲁克特里人的女先知韦勒达预言日耳曼人将要胜利，塔西佗说她住在利珀河边的一座塔里，不让人见面，由亲属传话。到这年年底，维特利乌斯已死，奇维利斯却没有放下武器。',
    who: ['尤利乌斯·奇维利斯', '韦勒达'] },
  { y: 70, mo: 2, t: '韦斯巴芗在亚历山大里亚', p: '亚历山大里亚', m: '今埃及亚历山大', ll: [29.92, 31.2], k: 'pol', refs: ['塔西佗·历史', '苏埃托尼乌斯·韦斯巴芗传'],
    d: '韦斯巴芗在亚历山大里亚等候季风，控制着罗马的粮仓埃及。一个盲人跪在他的面前，塔西佗写道：**他恳求韦斯巴芗屈尊用唾液涂抹他的面颊与眼球||He begged Vespasian that he would deign to moisten his cheeks and eye-balls with his spittle**，说这是塞拉皮斯神在梦中指点的。韦斯巴芗起初一笑了之，在医生的劝说下当众一试，据说盲人重见光明，另一个手残的人也痊愈了。出身寒微的新皇帝缺少奥古斯都家族的神圣光环，这样的奇迹正好为他赢得了民心。罗马城里由穆基阿努斯代为主持朝政，提图斯留在犹太继续攻打耶路撒冷。',
    who: ['韦斯巴芗', '穆基阿努斯'] },
  { y: 70, mo: 3, t: '“高卢帝国”', p: '奥古斯塔·特雷维罗鲁姆', m: '今德国莱茵兰-普法尔茨州特里尔', ll: [6.64, 49.75], k: 'war', refs: ['塔西佗·历史'],
    d: '特雷维里人的克拉西库斯、图托尔与林贡人的萨比努斯响应奇维利斯，宣布建立“高卢帝国”。维泰拉营地饥饿的守军投降，出营后在路上被屠杀，莱茵河上的两个军团竟向高卢人宣誓效忠。罗马的统治在莱茵河上几乎全面崩溃。不过高卢的大多数城市拒绝跟随，雷米人召集各城的代表开会，决定继续忠于罗马。',
    who: ['尤利乌斯·奇维利斯'] },
  { y: 70, mo: 7, t: '凯里亚利斯收复特雷维里', p: '里戈杜鲁姆', m: '今德国莱茵兰-普法尔茨州里奥尔', ll: [6.88, 49.83], k: 'war', refs: ['塔西佗·历史'],
    d: '韦斯巴芗派亲戚佩蒂利乌斯·凯里亚利斯率八个军团北上，在里戈杜鲁姆击败特雷维里人，进入他们的城市。他召集特雷维里人与林贡人训话，塔西佗记下了这篇为罗马统治辩护的著名演说：**在你们服从我们的统治之前，高卢一直是小王国林立、内战不休||Gaul always had its petty kingdoms and intestine wars, till you submitted to our authority**；各民族的安宁离不开军队，军队离不开军饷，军饷离不开赋税，除此之外，罗马人与高卢人一切共享。',
    who: ['凯里亚利斯'] },
  { y: 70, mo: 8, t: '耶路撒冷陷落', p: '耶路撒冷', m: '今耶路撒冷老城', ll: [35.23, 31.78], k: 'war', refs: ['约瑟夫斯·犹太战记', '考古'],
    d: '这年逾越节前后，提图斯率四个军团围攻耶路撒冷。城中的吉斯卡拉的约翰与西门·巴尔·吉奥拉两派互相残杀，烧掉了城里的存粮，被围的人饿得吃皮带与草，约瑟夫斯在城下劝降，被城上的人用石头打伤。罗马人筑起围墙，攻破第三道、第二道城墙，夺取安东尼亚堡，八月底冲进圣殿的院子。约瑟夫斯说提图斯本想保住圣殿，一个士兵却把火把扔了进去：**圣殿燃烧之时，凡是能拿到的都被抢走，被抓住的人有一万被杀||While the holy house was on fire, every thing was plundered that came to hand, and ten thousand of those that were caught were slain**。九月上城陷落，全城被夷平，只留下三座塔楼与一段西墙。约瑟夫斯说战争中死了一百一十万人，这个数字显然夸大，但被卖为奴隶的有近十万人。圣殿再也没有重建，犹太教从此以会堂与经书为中心。',
    who: ['提图斯', '约瑟夫斯', '吉斯卡拉的约翰', '西门·巴尔·吉奥拉'] },
  { y: 70, mo: 9, t: '约哈难·本·撒该与亚夫内的学院', p: '亚夫内', m: '今以色列中部亚夫内', ll: [34.74, 31.88], k: 'cul', refs: ['后世文献'],
    d: '拉比文献讲述，围城期间，法利赛派的长老约哈难·本·撒该让弟子把他装在棺材里抬出城外，求见罗马统帅，只要了一样东西：允许他在海边的小城亚夫内开设学堂。圣殿被毁、祭司与撒都该派失去根基之后，亚夫内的拉比们整理口传律法，确定圣经的正典，以祈祷代替献祭，后世的拉比犹太教由此而来。',
    who: ['约哈难·本·撒该'] },
  { y: 70, mo: 10, t: '奇维利斯议和', p: '巴达维岛', m: '今荷兰海尔德兰省', ll: [5.6, 51.9], k: 'dip', refs: ['塔西佗·历史'],
    d: '凯里亚利斯在维泰拉营地附近与奇维利斯决战，又进入巴达维人的岛屿，莱茵河东岸的日耳曼人逐渐与奇维利斯离心。秋天，奇维利斯在一座拆断的桥上与凯里亚利斯会面，说自己当初是为韦斯巴芗而战。塔西佗的《历史》在这里中断，巴达维人重新成为罗马的盟友，此后继续为罗马提供骑兵与皇帝的卫队。',
    who: ['尤利乌斯·奇维利斯', '凯里亚利斯'] },
  { y: 71, mo: 6, t: '韦斯巴芗与提图斯的凯旋式', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'pol', refs: ['约瑟夫斯·犹太战记', '考古'],
    d: '父子二人在罗马举行了平定犹太的凯旋式，图密善骑马随行。约瑟夫斯亲眼看到了游行，他描写从圣殿掠来的金灯台：**这些灯共有七盏，象征七这个数字在犹太人中的尊贵；在所有战利品的最后，抬着的是犹太人的律法||These lamps were in number seven, and represented the dignity of the number seven among the Jews; and the last of all the spoils, was carried the Law of the Jews**。西门·巴尔·吉奥拉在游行结束时被拖到广场上处死。犹太人此后每年要向卡皮托的朱庇特神庙缴纳原先交给圣殿的两德拉克马，称为“犹太税”。图密善后来在圣道上为死去的兄长建起提图斯凯旋门，门洞里的浮雕至今还能看到士兵们扛着七枝灯台。',
    who: ['韦斯巴芗', '提图斯', '图密善', '约瑟夫斯', '西门·巴尔·吉奥拉'] },
  { y: 71, mo: 7, t: '凯里亚利斯征服布里甘特', p: '埃博拉库姆', m: '今英国约克', ll: [-1.08, 53.96], k: 'war', refs: ['塔西佗·阿古利可拉传', '考古'],
    d: '四帝之年里，布里甘特的女王卡蒂曼杜阿被前夫维努提乌斯赶下王位，罗马失去了北方最重要的盟友。平定巴达维人之后，凯里亚利斯被派到不列颠任总督，带着第九军团北上，经过多次血战征服了布里甘特人的大部分土地，在乌斯河畔建立了埃博拉库姆营地，就是后来的约克。阿古利可拉这时在他麾下统领第二十军团。',
    who: ['凯里亚利斯', '阿古利可拉'] },
  { y: 72, mo: 3, t: '韦斯巴芗整顿财政与修建大斗兽场', p: '罗马', m: '今意大利罗马', ll: [12.49, 41.89], k: 'eco', refs: ['苏埃托尼乌斯·韦斯巴芗传', '考古'],
    d: '内战之后国库空虚，韦斯巴芗说要四百亿塞斯特斯才能让国家重新站起来。他恢复了被加尔巴免除的税，加重行省的贡赋，连公厕的尿也要征税，因为洗衣作坊要用尿来漂白羊毛。苏埃托尼乌斯说：**儿子提图斯责备他连尿都要征税，他把第一笔税款中的一枚钱币凑到儿子的鼻子前，问他是不是臭||When his son Titus blamed him for even laying a tax upon urine, he applied to his nose a piece of the money he received in the first instalment, and asked him, "if it stunk?"**。他把尼禄的金宫拆掉一部分还给公众，在金宫的人工湖上开工修建弗拉维圆形剧场，也就是后来所说的大斗兽场；又修建了和平神殿，陈列从耶路撒冷掠来的珍宝。他又取消了亚该亚、吕基亚、罗得岛、拜占庭、萨摩斯等地的自由，把它们重新并入行省。',
    who: ['韦斯巴芗', '提图斯'] },
  { y: 72, mo: 9, t: '科马基尼被吞并', p: '萨莫萨塔', m: '今土耳其阿德亚曼省', ll: [38.52, 37.53], k: 'pol', refs: ['约瑟夫斯·犹太战记'],
    d: '约瑟夫斯说：**在韦斯巴芗在位的第四年，科马基尼国王安条克与他的全家遭遇了大难||in the fourth year of the reign of Vespasian, it came to pass that Antiochus, the king of Commagene, with all his family, fell into very great calamities**。叙利亚总督帕伊图斯诬告这位一向忠于罗马的老国王与帕提亚勾结，率军进入科马基尼，安条克四世不战而走，被押往罗马，得到优待善终。科马基尼与小亚美尼亚并入行省，罗马在幼发拉底河上游设立了军团营地。同一时期阿兰人从高加索的山口南下，劫掠米底与亚美尼亚，帕提亚王沃洛加西斯一世向罗马求援，韦斯巴芗没有答应。',
    who: ['韦斯巴芗', '沃洛加西斯一世'] },
  { y: 73, mo: 4, t: '马萨达', p: '马萨达', m: '今以色列南区死海西岸', ll: [35.35, 31.31], k: 'war', refs: ['约瑟夫斯·犹太战记', '考古'],
    d: '耶路撒冷陷落后，以利亚撒·本·雅伊尔率领的激进派“短刀党”据守死海边的山顶要塞马萨达。犹太总督弗拉维乌斯·席尔瓦率第十军团围城，在山的西侧用土石堆起一道巨大的斜坡，把攻城塔推上山顶。城破前夜，约瑟夫斯记下了以利亚撒的演说：**我们早就决心不做罗马人的奴仆，也不做任何人的奴仆，只服从上帝||Since we, long ago, my generous friends, resolved never to be servants to the Romans, nor to any other than to God himself**。守军抽签先杀死自己的妻儿，再互相杀死，最后一人放火后自尽。第二天早上罗马人冲进来，只有两个妇女和五个孩子从地下水道里出来，**其余的人共有九百六十人，妇女和儿童也计算在内||Those others were nine hundred and sixty in number, the women and children being withal included in that computation**。罗马人的围城营地与斜坡至今仍在。',
    who: ['以利亚撒·本·雅伊尔'] },
  { y: 74, mo: 6, t: '什一税地', p: '阿尔塔埃·弗拉维埃', m: '今德国巴登-符腾堡州罗特韦尔', ll: [8.62, 48.17], k: 'war', refs: ['塔西佗·阿古利可拉传', '考古'],
    d: '上日耳曼总督克莱门斯修筑了一条从斯特拉斯堡穿过黑森林通往多瑙河上游的大道，把莱茵河与多瑙河之间的三角地带纳入帝国，以韦斯巴芗家族的名字建立了阿尔塔埃·弗拉维埃。塔西佗在《日耳曼尼亚志》里说，这片土地由高卢来的冒险者居住，向罗马缴纳什一税，后世称为“什一税地”。罗马的边界从此向东推出，莱茵河上游与多瑙河之间的路程大大缩短。',
    who: ['韦斯巴芗'] },
  { y: 77, mo: 8, t: '阿古利可拉到不列颠', p: '莫纳岛', m: '今英国威尔士安格尔西岛', ll: [-4.35, 53.27], k: 'war', refs: ['塔西佗·阿古利可拉传'],
    d: '阿古利可拉被任命为不列颠总督，他是塔西佗的岳父，塔西佗为他写的传记是这一时期不列颠的主要史料。他一到任就在夏末出兵消灭了威尔士北部的奥陶维塞人，又让辅助骑兵泅水渡过海峡，攻占了德鲁伊教的中心莫纳岛。此后他在各地鼓励修建神殿、广场与住宅，让首领的子弟学习拉丁语与修辞，塔西佗冷冷地写道：**他们把这些叫作文明，其实这是他们受奴役的一部分||this, from their inexperience, they termed politeness, whilst, in reality, it constituted a part of their slavery**。',
    who: ['阿古利可拉'] },
  { y: 79, mo: 6, t: '韦斯巴芗之死', p: '库提利埃', m: '今意大利列蒂省', ll: [13.08, 42.37], k: 'pol', refs: ['苏埃托尼乌斯·韦斯巴芗传'],
    d: '韦斯巴芗晚年在萨宾故乡的库提利埃泉水边避暑时病倒。他至死仍保持着幽默，苏埃托尼乌斯说他刚发病时就说：**“我想我快要成神了。”||"I suppose." he said, "I shall soon be a god."**按惯例，死去的皇帝会被元老院奉为神。病重时他仍坚持处理公务，在床上接见使节，最后挣扎着要起身，说：**“皇帝应该站着死。”||"An emperor ought to die standing upright."**他死在扶他起来的人手中，终年六十九岁。他是第一位由儿子和平继位的皇帝，长子提图斯即位。',
    who: ['韦斯巴芗', '提图斯'] },
  { y: 79, mo: 10, t: '维苏威火山爆发', p: '庞贝', m: '今意大利那不勒斯省', ll: [14.48, 40.75], k: 'cul', refs: ['小普林尼·书信', '考古'],
    d: '这年秋天，维苏威火山爆发，火山灰与浮石掩埋了庞贝，炽热的碎屑流吞没了赫库兰尼姆与斯塔比伊。小普林尼的书信传统上把日期写作八月二十四日，庞贝出土的秋季果实与一条炭笔题字显示可能是十月。当时十七岁的小普林尼在海湾对面的米塞努姆，他后来写信给塔西佗，描述他舅舅看到的那朵云：**我找不到比松树更恰当的比喻来形容它的样子，它像一根极高的树干直冲上天，到顶上又张开成许多枝杈||the appearance of which I cannot give you a more exact description of than by likening it to that of a pine tree, for it shot up to a great height in the form of a very tall trunk, which spread itself out at the top into a sort of branches**。他的舅舅、《博物志》的作者老普林尼是西部舰队的司令，带着战船前去救人，在斯塔比伊的海滩上死于毒烟。第二天白昼如夜，小普林尼扶着母亲在逃难的人群里摸索，他说唯一的安慰是：**全人类都卷进了同一场灾难，我是与整个世界一同毁灭||all mankind were involved in the same calamity, and that I was perishing with the world itself**。十八世纪人们开始发掘庞贝，凝固在火山灰里的城市与人形，成了今天了解罗马日常生活的宝库。',
    who: ['小普林尼', '老普林尼', '提图斯'] },
  { y: 80, mo: 6, t: '大斗兽场落成', p: '罗马', m: '今意大利罗马', ll: [12.49, 41.89], k: 'cul', refs: ['苏埃托尼乌斯·提图斯传', '考古'],
    d: '这年罗马又遭大火，三天三夜烧毁了卡皮托的朱庇特神庙与万神殿。同一年，韦斯巴芗开工的弗拉维圆形剧场完工，四层看台可以容纳五万人，场上可以拉起遮阳的巨幔。苏埃托尼乌斯说提图斯为落成举行了极其壮观的庆典：**他献出了自己的圆形剧场，又在旁边飞快地建起浴场||Having dedicated his amphitheatre, and built some warm baths close by it with great expedition**，又在旧的海战池里上演海战，**一天之内就往剧场里放进了五千头各种各样的野兽||in one day brought into the theatre five thousand wild beasts of all kinds**。庆典持续了一百天。中世纪时人们因为旁边尼禄的巨像，把它叫作“大斗兽场”。',
    who: ['提图斯'] },
  { y: 81, mo: 9, t: '提图斯病逝，图密善即位', p: '库提利埃', m: '今意大利列蒂省', ll: [13.08, 42.37], k: 'pol', refs: ['苏埃托尼乌斯·提图斯传', '苏埃托尼乌斯·图密善传'],
    d: '提图斯即位前名声不佳，人们担心他会成为又一个尼禄，他却以宽厚著称。他与犹太公主贝雷妮丝相恋多年，元老院与民众不愿看到一个东方王后，他即位后**立刻把贝雷妮丝送出罗马城，两人都极不情愿||He immediately sent away Berenice from the city, much against both their inclinations**。一天晚餐时，他想起这一天没有给任何人帮过忙，说出了那句有名的话：**“朋友们，我虚度了一天。”||"My friends, I have lost a day."**在位仅两年零两个月，他在去萨宾故乡的路上发高烧死去，年仅四十一岁。弟弟图密善即位，苏埃托尼乌斯说他**在位之初每天独自待上一个小时，什么也不做，只是捉苍蝇，用尖针把它们刺穿||In the beginning of his reign, he used to spend daily an hour by himself in private, during which time he did nothing else but catch flies, and stick them through the body with a sharp pin**。',
    who: ['提图斯', '图密善', '贝雷妮丝'] },
  { y: 83, mo: 6, t: '图密善征卡蒂人', p: '莫贡提亚库姆', m: '今德国莱茵兰-普法尔茨州美因茨', ll: [8.27, 50.0], k: 'war', refs: ['苏埃托尼乌斯·图密善传', '考古'],
    d: '图密善亲自从美因茨出兵，进攻陶努斯山一带的卡蒂人，在山林中开出一百多公里的道路，沿途设立瞭望塔与堡垒，这是后来日耳曼长墙的开端。他得胜回朝，举行凯旋式，取了“日耳曼征服者”的称号。塔西佗与小普林尼都讥讽这场胜利不过是一场作秀，但考古发现韦特劳地区的堡垒确实是这时修建的，罗马的边界由此从莱茵河推进到了陶努斯山后。',
    who: ['图密善'] },
  { y: 83, mo: 9, t: '格劳庇乌山之战', p: '格劳庇乌山', m: '今英国苏格兰阿伯丁郡一带（确切地点不详）', ll: [-2.6, 57.2], k: 'war', refs: ['塔西佗·阿古利可拉传'],
    d: '阿古利可拉连续六年北进，在福斯湾与克莱德湾之间修筑堡垒，又让舰队沿海岸配合。第七年夏天，喀里多尼亚诸部集合了三万多人，在格劳庇乌山迎战。塔西佗让他们的首领卡尔加库斯在战前发表了一篇演说，痛斥罗马人是**世界的掠夺者||These plunderers of the world**：**掠夺、屠杀、抢劫，他们称之为帝国；他们造成一片荒漠，却称之为和平||To ravage, to slaughter, to usurp under false titles, they call empire; and where they make a desert, they call it peace**。阿古利可拉只用辅助部队就击溃了不列颠人，据说杀死一万人，罗马军团连阵也没有上。随后他的舰队绕过苏格兰北端，证明不列颠是一个岛。第二年他被图密善召回，塔西佗认为是皇帝嫉妒他的战功。他曾说用一个军团就能征服爱尔兰，这个计划再也没有实现。',
    who: ['阿古利可拉', '卡尔加库斯', '图密善'] },
  { y: 86, mo: 6, t: '达契亚人越过多瑙河', p: '默西亚', m: '今保加利亚北部与塞尔维亚东部', ll: [24.0, 43.6], k: 'war', refs: ['苏埃托尼乌斯·图密善传', '后世文献'],
    d: '多瑙河北岸的达契亚人在德西巴卢斯的领导下重新统一。这年冬天他们越过结冰的多瑙河，攻入默西亚，杀死了总督奥皮乌斯·萨比努斯。图密善亲临多瑙河，把默西亚分为上下两个行省，派近卫军长官科尔内利乌斯·弗斯库斯渡河反攻，弗斯库斯却在达契亚的山林中中伏，全军覆没，军团的鹰旗落入敌手。为了增援多瑙河，罗马从不列颠调走一个军团，阿古利可拉在苏格兰修建的堡垒随之放弃。卡西乌斯·狄奥说德西巴卢斯精通兵法，知道何时进攻、何时撤退，善于设伏，也懂得如何利用胜利。',
    who: ['德西巴卢斯', '图密善'] },
  { y: 89, mo: 6, t: '与德西巴卢斯议和', p: '塔佩', m: '今罗马尼亚卡拉什-塞维林县铁门关一带', ll: [22.4, 45.4], k: 'dip', refs: ['苏埃托尼乌斯·图密善传', '后世文献'],
    d: '公元 88 年，泰提乌斯·尤利安努斯在通往达契亚王都的塔佩山口击败达契亚人。正要乘胜追击时，次年一月上日耳曼总督萨图尔尼努斯在美因茨起兵造反，图密善不得不转向莱茵河，叛乱很快被平定。随后马科曼尼人、夸狄人又在潘诺尼亚作乱，图密善只好与德西巴卢斯议和：达契亚王承认罗马的宗主权，罗马却要每年给他补助金，还派去工匠与技师。罗马人认为这是用钱买来的和平，德西巴卢斯借机修筑山城，积蓄力量。',
    who: ['图密善', '德西巴卢斯'] },
  { y: 93, mo: 6, t: '图密善驱逐哲学家', p: '尼科波利斯', m: '今希腊普雷韦扎北', ll: [20.73, 39.01], k: 'cul', refs: ['爱比克泰德·语录', '塔西佗·阿古利可拉传'],
    d: '萨图尔尼努斯的叛乱之后，图密善变得越来越多疑，告密者遍布罗马，一批批元老被以叛国罪处死。这年阿古利可拉去世，塔西佗说他幸而没有看到后来的大清洗。斯多亚派的哲学家因为赞颂反对暴君的先贤而被视为危险人物，图密善两次把哲学家逐出罗马与意大利。曾经是奴隶的爱比克泰德来到希腊的尼科波利斯开设学校，他的学生阿里安后来记下了他的讲话，开头就是：**要分清哪些事在我们的力量之内，哪些不在||to distinguish that of things some are in our power, but others are not**；意志与一切取决于意志的行为在我们的力量之内，身体、财产、父母、国家都不在。他的学说两代人之后成了马可·奥勒留的精神支柱。也是在这一年前后，犹太地的最后一位国王亚基帕二世死去，他的封地并入叙利亚行省。',
    who: ['爱比克泰德', '图密善', '阿古利可拉', '希律·亚基帕二世'] },
  { y: 95, mo: 6, t: '拔摩岛的约翰', p: '拔摩岛', m: '今希腊佐泽卡尼索斯群岛帕特莫斯岛', ll: [26.55, 37.32], k: 'cul', refs: ['新约', '后世文献'],
    d: '据教会的传统，图密善晚年迫害基督徒，一个名叫约翰的基督徒先知被流放到爱琴海的小岛拔摩，在那里写下了《新约》的最后一卷《启示录》：**我约翰就是你们的弟兄，和你们在耶稣的患难、国度、忍耐里一同有份，为上帝的道并为给耶稣作的见证，曾在那名叫拔摩的海岛上||I John, who also am your brother, and companion in tribulation, and in the kingdom and patience of Jesus Christ, was in the isle that is called Patmos, for the word of God, and for the testimony of Jesus Christ**。书中把罗马写成坐在七座山上的大淫妇巴比伦，那个数目是六百六十六的兽，许多学者认为指的是尼禄。这一年图密善还处死了自己的堂兄弗拉维乌斯·克莱门斯，克莱门斯的妻子多米提拉被流放，后世的基督徒说他们夫妇是信徒。',
    who: ['拔摩的约翰', '图密善'] },
  { y: 96, mo: 9, t: '图密善遇刺', p: '罗马', m: '今意大利罗马帕拉丁山', ll: [12.49, 41.89], k: 'pol', refs: ['苏埃托尼乌斯·图密善传'],
    d: '图密善要求臣下称他为“主人与神”，在剧场里听到民众欢呼**祝我们的主人与女主人万事如意||All happiness to our lord and lady**，十分得意。宫中的人人人自危，连皇后多米提娅与两个近卫军长官都参与了密谋。九月十八日，多米提拉的管家斯蒂芬努斯假装手臂受伤，在绷带里藏了一把匕首，借口告发阴谋进入皇帝的寝室。图密善与他扭打了很久，**一会儿想夺下匕首，一会儿用手指去挖他的眼睛，手指被割得血肉模糊||one while endeavouring to wrench the dagger from him, another while, though his fingers were miserably mangled, to tear out his eyes**，最后被冲进来的同谋者刺死，年四十四岁。元老院下令毁去他的名字与雕像，当天推举六十多岁的老元老涅尔瓦为帝。',
    who: ['图密善', '涅尔瓦'] },
  { y: 97, mo: 6, t: '甘英出使大秦', p: '卡拉克斯', m: '今伊拉克巴士拉省北', ll: [47.8, 30.9], k: 'dip', refs: ['后汉书'],
    d: '东汉的西域都护班超平定西域之后，在永元九年（公元 97 年）派掾吏甘英出使大秦，也就是罗马。《后汉书·西域传》说甘英穿过安息，到了条支，“临大海欲度，而安息西界船人谓英曰：‘海水广大，往来者逢善风三月乃得度，若遇迟风，亦有二岁者，故入海人皆赍三岁粮。海中善使人思土恋慕，数有死亡者。’英闻之乃止。”帕提亚人垄断着东西方的丝绸贸易，不愿让汉朝与罗马直接往来。甘英到达的“大海”可能是波斯湾，也有人认为是地中海或黑海。这是汉朝的使者离罗马最近的一次。',
    who: [] },
  { y: 98, mo: 1, t: '图拉真即位', p: '科洛尼亚·阿格里皮纳', m: '今德国北莱茵-威斯特法伦州科隆', ll: [6.96, 50.94], k: 'pol', refs: ['塔西佗·历史', '后世文献'],
    d: '涅尔瓦即位后召回流放的人，减轻赋税，但军队怀念图密善，近卫军包围皇宫，逼他交出刺杀图密善的人。年老无子的涅尔瓦在公元 97 年十月登上卡皮托山，宣布收养正在上日耳曼统兵的图拉真。三个月后涅尔瓦去世，图拉真在科洛尼亚·阿格里皮纳得到消息，他是第一位出身行省的皇帝，家族来自西班牙的意大利卡。他没有急着回罗马，先巡视了莱茵河与多瑙河的防线。塔西佗在这时开始写他的史书，他说在神圣的涅尔瓦与图拉真的统治下，人们终于**享受到难得的幸福时代，可以想自己愿意想的，说自己所想的||enjoying the rare happiness of times, when we may think what we please, and express what we think**。',
    who: ['图拉真', '涅尔瓦', '塔西佗'] },
  { y: 98, mo: 6, t: '塔西佗的《阿古利可拉传》与《日耳曼尼亚志》', p: '罗马', m: '今意大利罗马', ll: [12.5, 41.9], k: 'cul', refs: ['塔西佗·阿古利可拉传'],
    d: '图密善死后，塔西佗发表了岳父阿古利可拉的传记，接着写了一篇描述莱茵河以东各部族的《日耳曼尼亚志》。他说：**我赞同这样的看法：日耳曼人从未与别的民族通婚，是一个纯粹、未经混杂、具有独特性格的民族||I concur in opinion with those who deem the Germans never to have intermarried with other nations; but to be a race, pure, unmixed, and stamped with a distinct character**，他们的眼睛是蓝色的，头发是红色的，身材高大。他笔下的日耳曼人勇敢、淳朴、重视贞洁，常常是在借野蛮人的美德讽刺罗马的堕落。这部小书在文艺复兴时被重新发现，后来被德意志民族主义者奉为经典，又被纳粹拿来宣扬种族纯洁，被称为“最危险的书之一”。',
    who: ['塔西佗', '阿古利可拉'], post: ['阿古利可拉'] },
  { y: 100, mo: 6, t: '普鲁塔克写《名人传》', p: '喀罗尼亚', m: '今希腊维奥蒂亚州', ll: [22.84, 38.49], k: 'cul', refs: ['普鲁塔克·名人传'],
    d: '维奥蒂亚小城喀罗尼亚的普鲁塔克在雅典学过哲学，到过亚历山大里亚与罗马，晚年在德尔斐担任阿波罗神庙的祭司。他把希腊与罗马的名人两两配对写传，如亚历山大与恺撒、狄摩西尼与西塞罗，合称《希腊罗马名人传》，又写了七十多篇杂论。他在《亚历山大传》的开头说：**我写的不是历史，而是传记||For it is not Histories that I am writing, but Lives**，一句话、一个玩笑，往往比死伤成千上万的战役更能显出人的品格。这部书文艺复兴以后在欧洲流传极广，莎士比亚的《裘力斯·恺撒》《安东尼与克莉奥佩特拉》都取材于它，本书许多卷的引文也出自这里。',
    who: ['普鲁塔克'] },
  { y: 101, mo: 9, t: '第一次达契亚战争', p: '塔佩', m: '今罗马尼亚卡拉什-塞维林县铁门关一带', ll: [22.4, 45.4], k: 'war', refs: ['后世文献', '考古'],
    d: '图拉真不愿再向德西巴卢斯缴纳补助金，亲率九个军团从多瑙河上的维米纳基乌姆渡河北进，在铁门峡的岩壁上凿出栈道运送补给。这年秋天两军在塔佩再次交锋，伤亡惨重，据说图拉真把自己的衣服撕开给伤员包扎。次年罗马军逼近达契亚的王都萨尔米泽格图萨，德西巴卢斯求和，交出武器与工匠，拆除堡垒，接受罗马驻军。图拉真回到罗马举行凯旋式，取得“达契亚征服者”的称号。',
    who: ['图拉真', '德西巴卢斯'] },
  { y: 105, mo: 6, t: '多瑙河大桥', p: '德罗贝塔', m: '今罗马尼亚塞维林堡', ll: [22.66, 44.63], k: 'eco', refs: ['后世文献', '考古'],
    d: '德西巴卢斯并没有遵守和约，他重新修筑堡垒，招纳罗马的逃兵，攻击邻近的雅济吉斯人。图拉真命叙利亚大马士革出身的建筑师阿波罗多洛斯在德罗贝塔架起一座横跨多瑙河的大桥，二十座石砌桥墩上搭着木拱，全长一千一百多米，此后一千年间都是世界上最长的拱桥。公元 105 年夏天，德西巴卢斯扣押了罗马的将领朗吉努斯，战争再起，图拉真经过这座桥第二次进入达契亚。今天塞维林堡的多瑙河两岸还能看到桥墩的残迹。',
    who: ['图拉真', '阿波罗多洛斯', '德西巴卢斯'] },
  { y: 106, mo: 3, t: '阿拉伯行省', p: '波斯特拉', m: '今叙利亚德拉省布斯拉', ll: [36.48, 32.52], k: 'pol', refs: ['考古'],
    d: '纳巴泰的末代国王拉贝尔二世死后，叙利亚总督科尔内利乌斯·帕尔马不经大战就吞并了这个控制着阿拉伯香料商路的王国，设为阿拉伯行省，首府从岩石之城佩特拉迁到波斯特拉。图拉真随即修筑了一条从波斯特拉直到红海边亚喀巴的“图拉真新路”。纳巴泰人的纪年从此改用行省纪元，这一年是“阿拉伯行省元年”。',
    who: ['图拉真'] },
  { y: 106, mo: 8, t: '萨尔米泽格图萨陷落，德西巴卢斯自杀', p: '萨尔米泽格图萨', m: '今罗马尼亚胡内多阿拉县奥勒什蒂耶山', ll: [23.31, 45.62], k: 'war', refs: ['后世文献', '考古'],
    d: '罗马军队从几路攻入奥勒什蒂耶山区，围攻达契亚的王都萨尔米泽格图萨，切断了城里的水源，城破后王宫被焚。德西巴卢斯带着少数骑兵逃走，被罗马骑兵追上时拔刀自刎。1965 年在希腊腓立比附近发现了骑兵提比略·克劳狄乌斯·马克西穆斯的墓碑，说是他把德西巴卢斯的首级送到图拉真的营中。图拉真找到了达契亚人藏在河床下的王室宝藏，据说有五百万罗马磅黄金，这笔财富支付了他在罗马的大兴土木与一百二十三天的庆典。达契亚设为行省，大批殖民者从帝国各地迁来，罗马尼亚人至今说的是一种拉丁语。',
    who: ['德西巴卢斯', '图拉真'] },
  { y: 112, mo: 9, t: '小普林尼论基督徒', p: '阿马斯特里斯', m: '今土耳其巴尔腾省阿马斯拉', ll: [32.38, 41.75], k: 'cul', refs: ['小普林尼·书信'],
    d: '小普林尼被图拉真派往比提尼亚与本都整顿财政，他事无巨细都写信请示皇帝，从尼科米底亚的救火队到尼西亚的剧院，这些公文都保存了下来。有人向他告发基督徒，他写信说：**我问他们是不是基督徒，如果承认，我就再问两遍，并以刑罚相威胁；如果坚持，我就下令处死||I asked them whether they were Christians; if they admitted it, I repeated the question twice, and threatened them with punishment; if they persisted, I ordered them to be at once punished**。他审问之后发现，他们只是在固定的日子天亮前聚会，向基督像向神一样唱赞歌，发誓不偷盗、不奸淫、不背信。图拉真回信说：**不要特意去搜捕他们||Do not go out of your way to look for them**，有人告发且查实的才要处罚，**匿名的告发在任何案件中都不应受理||Anonymous informations ought not to be received in any sort of prosecution**。这是非基督徒作家对基督徒最早的记载之一，此后一百多年，罗马对基督徒大体就是这样处置的。',
    who: ['小普林尼', '图拉真'] },
  { y: 113, mo: 5, t: '图拉真纪功柱', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.9], k: 'cul', refs: ['考古'],
    d: '阿波罗多洛斯为图拉真设计的广场在罗马落成，有巨大的乌尔皮亚会堂、拉丁文与希腊文两座图书馆和一座半圆形的市场。广场中央竖起一根高约三十米的大理石柱，一条长两百米的浮雕带像画卷一样盘旋而上，刻着两次达契亚战争的经过：渡过多瑙河、修筑营地、攻城、德西巴卢斯自杀，共有两千五百多个人物，是了解罗马军队的最重要的图像资料。基座的铭文说，柱子的高度标出了为修建广场削平的山丘的高度。图拉真死后，他的骨灰就安放在柱基里。',
    who: ['图拉真', '阿波罗多洛斯'] },
  { y: 114, mo: 6, t: '吞并亚美尼亚', p: '埃勒格亚', m: '今土耳其埃尔祖鲁姆省', ll: [41.07, 39.95], k: 'war', refs: ['后世文献'],
    d: '帕提亚王奥斯罗埃斯一世废黜了亚美尼亚国王，未经罗马同意就立自己的侄子帕尔塔马西里斯为王，破坏了尼禄时达成的妥协。图拉真认为这是对罗马的冒犯，亲率大军东征。帕尔塔马西里斯来到埃勒格亚的罗马营中，摘下王冠放在图拉真脚下，希望像梯里达底一样被罗马重新加冕，图拉真却宣布亚美尼亚从此是罗马的行省。帕尔塔马西里斯在离营的路上被杀。',
    who: ['图拉真', '帕尔塔马西里斯', '奥斯罗埃斯一世'] },
  { y: 115, mo: 6, t: '美索不达米亚行省', p: '尼西比斯', m: '今土耳其马尔丁省努赛宾', ll: [41.22, 37.07], k: 'war', refs: ['后世文献', '考古'],
    d: '公元 115 年，图拉真南下美索不达米亚北部，奥斯若恩国王阿布加尔七世献上礼物，派儿子为图拉真跳舞。罗马军队攻取尼西比斯与辛加拉，设立美索不达米亚行省；毛里人出身的骑兵将领卢西乌斯·奎图斯在北方作战，接着又渡过底格里斯河，攻取了阿迪亚贝尼，设为亚述行省。',
    who: ['图拉真', '卢西乌斯·奎图斯'] },
  { y: 115, mo: 9, t: '流散犹太人的起义', p: '昔兰尼', m: '今利比亚绿山省夏哈特', ll: [21.86, 32.82], k: 'war', refs: ['后世文献'],
    d: '图拉真在东方作战时，昔兰尼的犹太人在一个叫卢库阿斯的人领导下起义，杀死希腊居民，捣毁神庙，接着埃及与塞浦路斯的犹太人也起来响应。据卡西乌斯·狄奥的说法，昔兰尼死了二十二万人，塞浦路斯死了二十四万人，此后塞浦路斯禁止犹太人登岛。亚历山大里亚有数百年历史的犹太社区几乎被毁灭，美索不达米亚的犹太人也起而反抗罗马的占领。图拉真派马尔奇乌斯·图尔博与卢西乌斯·奎图斯残酷镇压，到公元 117 年才平息。犹太人称之为“基托斯战争”。',
    who: ['卢西乌斯·奎图斯'] },
  { y: 115, mo: 12, t: '安条克大地震', p: '安条克', m: '今土耳其哈塔伊省安塔基亚', ll: [36.16, 36.2], k: 'eco', refs: ['后世文献'],
    d: '这年冬天图拉真在叙利亚的首府安条克过冬，十二月发生了一场大地震，城里挤满了从帝国各地赶来的士兵、商人与使节，死伤无数。卡西乌斯·狄奥说图拉真从窗户里爬出去才逃过一死，此后几天露宿在赛马场里。当年的执政官佩多就死在废墟中。附近的卡西乌斯山的一座山峰据说也被震塌了。',
    who: ['图拉真'] },
  { y: 116, mo: 2, t: '攻陷泰西封', p: '泰西封', m: '今伊拉克巴格达东南', ll: [44.58, 33.09], k: 'war', refs: ['后世文献', '考古'],
    d: '公元 116 年初，图拉真的军队乘着在尼西比斯附近的森林里造好的船只沿幼发拉底河而下，再把船从陆上拖到底格里斯河，攻陷了塞琉西亚与帕提亚的冬都泰西封。奥斯罗埃斯一世出逃，他的女儿与黄金宝座落入罗马人手中。元老院授予图拉真“帕提亚征服者”的称号，罗马的钱币上铸出了“帕提亚被俘”的字样。',
    who: ['图拉真', '奥斯罗埃斯一世'] },
  { y: 116, mo: 6, t: '图拉真来到波斯湾', p: '卡拉克斯', m: '今伊拉克巴士拉省北', ll: [47.8, 30.9], k: 'war', refs: ['后世文献'],
    d: '图拉真顺底格里斯河而下，卡拉塞尼国王阿塔姆贝洛斯臣服。卡西乌斯·狄奥说他在海边看到一艘开往印度的船，叹道如果自己还年轻，一定也要渡海去印度，他羡慕亚历山大的幸运。他在给元老院的信里说自己走得比亚历山大还远。但他还在波斯湾时，刚征服的两河流域就已到处起义，塞琉西亚与尼西比斯杀死了罗马驻军，帕提亚的王族在北方反攻。图拉真只好退回泰西封，立帕提亚王子帕尔塔马斯帕特斯为附庸国王，围攻沙漠中的哈特拉城也没有成功。',
    who: ['图拉真'] },
  { y: 117, mo: 8, t: '图拉真病逝，哈德良放弃东方', p: '塞利努斯', m: '今土耳其安塔利亚省加济帕夏', ll: [32.27, 36.27], k: 'pol', refs: ['后世文献', '考古'],
    d: '六十四岁的图拉真在东方病倒，准备回罗马，船行到西里西亚的塞利努斯时中风去世。皇后普洛蒂娜宣布他临终前收养了叙利亚总督哈德良，有人怀疑这份收养文书是她伪造的。哈德良是图拉真的远亲，同样出身西班牙的意大利卡。他即位后立刻放弃了美索不达米亚与亚述，让亚美尼亚重新成为附庸王国，恢复了以幼发拉底河为界的旧边界。第二年，四名曾经身居高位的图拉真旧将，包括卢西乌斯·奎图斯，以谋反罪被元老院处死，哈德良与元老院的关系从此蒙上阴影。',
    who: ['图拉真', '哈德良', '普洛蒂娜', '卢西乌斯·奎图斯'] },
  { y: 120, mo: 6, t: '尤维纳利斯的讽刺诗', p: '罗马', m: '今意大利罗马', ll: [12.5, 41.89], k: 'cul', refs: ['尤维纳利斯·讽刺诗'],
    d: '尤维纳利斯在图拉真与哈德良时发表了十六首讽刺诗，痛骂罗马城里的拥挤、贫富悬殊、谄媚的门客与外国人。他说曾经授予统帅权与执政官职位的罗马人民，如今**只热切地盼望两样东西：面包和赛车场的竞技||limits its anxious longings to two things only--bread, and the games of the circus**。他讽刺丈夫们派人看守妻子：**可是谁来看守看守者自己呢？||But who is to guard the guards themselves?**又劝人们向神祈求：**祈求健全的身体里有健全的精神||your prayer must be that you may have a sound mind in a sound body**。这三句话后来都成了谚语。哈德良的秘书苏埃托尼乌斯也在这时写成了《罗马十二帝王传》。',
    who: ['尤维纳利斯', '苏埃托尼乌斯'] },
  { y: 122, mo: 6, t: '哈德良长城', p: '哈德良长城', m: '今英国英格兰北部', ll: [-2.3, 55.0], k: 'war', refs: ['后世文献', '考古'],
    d: '哈德良在位二十一年，有一半时间在巡行帝国，他到过几乎每一个行省，视察军队，主持操练，修建城市。公元 122 年他来到不列颠，下令在泰恩河口与索尔韦湾之间修筑一道长城，《罗马帝王纪》说它的用途是“把罗马人与蛮族分开”。长城全长约一百二十公里，东段用石头砌成，西段起初是草皮墙，每隔一罗马里设一座小堡，沿线有十几座大营，墙南还挖了一道深沟。长城附近的文多兰达营地出土的木牍书信里，有一位指挥官的妻子邀请友人来参加生日宴会。今天它是英国最有名的古迹，也是世界遗产。',
    who: ['哈德良'] },
  { y: 124, mo: 9, t: '哈德良在雅典', p: '雅典', m: '今希腊雅典', ll: [23.73, 37.98], k: 'cul', refs: ['后世文献', '考古'],
    d: '哈德良酷爱希腊文化，青年时被人戏称为“小希腊人”，他是第一个蓄须的罗马皇帝，据说就是为了模仿希腊哲学家。他多次到雅典，接受埃琉西斯秘仪的入会，为雅典修建图书馆、引水渠与新城区，完成了六百年前庇西特拉图开工的奥林匹亚宙斯神庙，又召集希腊各城组成“泛希腊同盟”。雅典人在新旧城区之间立起一座门，一面写着“这是忒修斯的雅典，古城”，另一面写着“这是哈德良的城，不是忒修斯的”。',
    who: ['哈德良'] },
  { y: 126, mo: 6, t: '万神殿重建', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.9], k: 'cul', refs: ['考古'],
    d: '公元 80 年被火烧毁的万神殿，在图拉真与哈德良时重建。新的万神殿是一座巨大的圆形殿堂，穹顶直径四十三米多，用越往上越轻的混凝土浇筑而成，顶上开着一个直径近九米的圆孔采光，此后一千三百年间都是世界上最大的穹顶。哈德良没有在门廊上写自己的名字，仍刻着一百多年前最初修建者阿格里帕的名字。七世纪万神殿被改为教堂，因此一直保存到今天，是古罗马保存最完整的建筑。哈德良还在罗马城外的蒂布尔修建了一座庞大的别墅，仿造他在各地见过的名胜。',
    who: ['哈德良'] },
  { y: 128, mo: 7, t: '兰拜西斯的检阅', p: '兰拜西斯', m: '今阿尔及利亚巴特纳省塔祖尔特', ll: [6.26, 35.49], k: 'war', refs: ['考古'],
    d: '哈德良巡视阿非利加，检阅了驻在努米底亚的第三奥古斯塔军团与辅助部队。军团在营地里竖起一座纪念碑，刻下了皇帝对士兵操练的讲评，这些讲话的原文保存至今，是罗马皇帝对军队讲话的唯一原始记录。他称赞骑兵在困难的地形上投掷标枪，又批评有的部队冲锋太快、队形散乱。哈德良放弃了扩张，却始终要求边境的军队保持严格的训练与纪律。',
    who: ['哈德良'] },
  { y: 130, mo: 10, t: '安提诺乌斯溺死尼罗河', p: '安提诺波利斯', m: '今埃及明亚省', ll: [30.88, 27.81], k: 'cul', refs: ['后世文献', '考古'],
    d: '哈德良的宠爱的比提尼亚少年安提诺乌斯随他游历埃及，十月在尼罗河上溺死，年约二十岁。他是失足、自杀还是被献祭，当时就众说纷纭，有人说他相信自己的死能延长皇帝的寿命。哈德良像女人一样痛哭，在他溺死的地方建立了安提诺波利斯城，把他奉为神，东方各地为他建立神庙、举行竞技，留下了几百座安提诺乌斯的雕像，在古代的雕像里数量仅次于奥古斯都与哈德良本人。皇后萨比娜也在这次旅行中，随行的女诗人在底比斯的门农巨像上刻诗，记下皇后听到了巨像在清晨发出的声音。',
    who: ['哈德良', '安提诺乌斯', '萨比娜'] },
  { y: 132, mo: 9, t: '巴尔·科赫巴起义', p: '犹地亚', m: '今以色列与巴勒斯坦西岸', ll: [35.1, 31.6], k: 'war', refs: ['后世文献', '考古'],
    d: '哈德良决定在耶路撒冷的废墟上建立一座罗马殖民地，以自己的家族名与卡皮托的朱庇特命名为爱利亚·加比多连，据说还禁止割礼。犹太人在西门·本·科西巴的领导下起义，他被拉比阿基巴称为“巴尔·科赫巴”，意为“星辰之子”，许多人认为他就是弥赛亚。起义军利用山洞与地道打游击，铸造了刻着“以色列自由第一年”的钱币，一度控制了犹地亚的大部分地区，一个罗马军团可能就在这里被歼灭。死海边的洞穴里发现了巴尔·科赫巴亲笔署名的书信。',
    who: ['巴尔·科赫巴', '阿基巴', '哈德良'] },
  { y: 135, mo: 8, t: '贝塔尔陷落', p: '贝塔尔', m: '今巴勒斯坦伯利恒省巴蒂尔', ll: [35.14, 31.73], k: 'war', refs: ['后世文献', '考古'],
    d: '哈德良从不列颠调来最好的将军尤利乌斯·塞维鲁，他避免正面决战，逐个围困起义者的据点，切断粮食。公元 135 年夏天，巴尔·科赫巴最后的据点贝塔尔陷落，他本人战死。卡西乌斯·狄奥说战争中有五十八万犹太人被杀，九百八十五个村庄被毁，罗马人也损失惨重，哈德良给元老院写信时省去了惯用的“我与军队都安好”。拉比阿基巴据说被罗马人用铁梳刮肉而死。哈德良把犹太行省改名为“叙利亚·巴勒斯坦”，禁止犹太人进入爱利亚·加比多连，只在每年圣殿被毁的纪念日准许他们到西墙下哀哭。此后一千八百年间，犹太人散居各地。',
    who: ['尤利乌斯·塞维鲁', '巴尔·科赫巴', '阿基巴', '哈德良'] },
  { y: 138, mo: 7, t: '哈德良之死', p: '巴亚', m: '今意大利那不勒斯省巴亚', ll: [14.07, 40.82], k: 'pol', refs: ['后世文献', '考古'],
    d: '哈德良晚年病痛缠身，几次要求仆人杀死自己。他先收养的继承人埃利乌斯早死，又在公元 138 年二月收养了元老安敦尼，条件是安敦尼要收养两个少年：埃利乌斯之子卢基乌斯与他看中的马可。七月他死在海边的巴亚，《罗马帝王纪》说他临终写了一首小诗：“小小的灵魂，飘忽而可爱，身体的客人与伴侣，你现在要去何方？”元老院因为他处死过许多元老，不愿把他奉为神，安敦尼坚持请求，才为他封神，因此得了“庇护”（孝敬）的称号。哈德良的陵墓就是今天罗马的圣天使堡。',
    who: ['哈德良', '安敦尼·庇护'] },
  { y: 142, mo: 6, t: '安敦尼长城', p: '安敦尼长城', m: '今英国苏格兰中部', ll: [-4.0, 55.95], k: 'war', refs: ['后世文献', '考古'],
    d: '安敦尼·庇护是一位温和、勤勉的皇帝，在位二十三年从未离开意大利，几乎没有战争。唯一的例外在不列颠：总督洛利乌斯·乌尔比库斯越过哈德良长城向北推进，在福斯湾与克莱德湾之间约六十公里的地峡上修筑了一道草皮墙，称为安敦尼长城。这道长城只守了二十年左右，到马可·奥勒留即位前后，罗马军队又退回了哈德良长城。',
    who: ['安敦尼·庇护'] },
  { y: 150, mo: 6, t: '托勒密的《天文学大成》与《地理学》', p: '亚历山大里亚', m: '今埃及亚历山大', ll: [29.92, 31.2], k: 'cul', refs: ['后世文献'],
    d: '亚历山大里亚的克劳狄乌斯·托勒密在安敦尼时写成了《数学汇编》，阿拉伯人称之为《至大论》，系统地阐述了地球居中、日月五星沿本轮与均轮运行的宇宙模型，这一体系统治了欧洲与伊斯兰世界的天文学一千四百年，直到哥白尼。他的《地理学》列出了八千多个地点的经纬度，教人用投影法绘制世界地图，书中提到东方产丝的“赛里斯”与港口“秦奈”，指的就是中国。',
    who: ['克劳狄乌斯·托勒密'] },
  { y: 155, mo: 2, t: '士麦那的波利卡普殉道', p: '士麦那', m: '今土耳其伊兹密尔', ll: [27.14, 38.42], k: 'cul', refs: ['后世文献'],
    d: '士麦那的主教波利卡普据说是使徒约翰的弟子，八十多岁时在一次节庆的竞技中被群众要求处死。士麦那教会写给各地教会的信记载，总督劝他咒骂基督就放他走，他回答：“我侍奉他八十六年，他从未亏待过我，我怎能亵渎救我的王？”他被绑在柴堆上烧死。这封信是最早的殉道者传记，此后教会开始纪念殉道者的忌日。同一时期，出身撒玛利亚的哲学家游斯丁在罗马开办学校，写信给安敦尼为基督徒辩护，约公元 165 年也在罗马殉道。',
    who: ['波利卡普', '游斯丁'] },
  { y: 161, mo: 3, t: '安敦尼·庇护之死与两帝共治', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'pol', refs: ['后世文献'],
    d: '安敦尼·庇护在罗马附近的庄园里去世，临终把守夜的口令定为“平静”，下令把象征好运的金像移到马可·奥勒留的房间。马可做了二十三年储君，即位后立刻坚持让义弟卢基乌斯·维鲁斯与他同为奥古斯都，罗马第一次有了两位地位平等的皇帝。马可从小醉心哲学，十二岁就穿上哲学家的粗布斗篷，睡在地上；他的老师弗朗托是当时最有名的拉丁修辞家，两人的书信有一部分保存到了今天。大约在这前后，罗马军队放弃了苏格兰的安敦尼长城，退回哈德良长城一线。',
    who: ['马可·奥勒留', '卢基乌斯·维鲁斯', '安敦尼·庇护', '弗朗托'] },
  { y: 161, mo: 9, t: '帕提亚入侵亚美尼亚', p: '埃勒格亚', m: '今土耳其埃尔祖鲁姆省', ll: [41.07, 39.95], k: 'war', refs: ['后世文献'],
    d: '安敦尼一死，帕提亚王沃洛加西斯四世就派军队进入亚美尼亚，立帕提亚王族帕科鲁斯为王。卡帕多西亚总督塞达提乌斯·塞维里亚努斯听信了一个自称先知的骗子的预言，率一个军团进入亚美尼亚，在埃勒格亚被帕提亚军包围，三天后全军覆没，他本人自杀。帕提亚军接着攻入叙利亚，打败了叙利亚总督。次年卢基乌斯·维鲁斯奉命东征，坐镇安条克。',
    who: ['沃洛加西斯四世', '卢基乌斯·维鲁斯'] },
  { y: 162, mo: 6, t: '盖伦来到罗马', p: '罗马', m: '今意大利罗马', ll: [12.5, 41.88], k: 'cul', refs: ['后世文献'],
    d: '帕加马的医生盖伦在家乡给角斗士治伤四年，积累了大量的解剖与外科经验，三十二岁来到罗马。他在公开场合解剖猪与猴子，演示切断喉返神经会让动物失声，名声大噪，后来成了马可·奥勒留与康茂德的御医。他写了几百部著作，继承希波克拉底的体液学说，以动物解剖推论人体结构，他的学说在欧洲与伊斯兰世界的医学中统治了一千多年，直到十六世纪的维萨里才纠正了其中的许多错误。',
    who: ['盖伦', '马可·奥勒留'] },
  { y: 163, mo: 6, t: '攻取阿尔塔沙特', p: '阿尔塔沙特', m: '今亚美尼亚阿拉拉特省', ll: [44.55, 39.96], k: 'war', refs: ['后世文献'],
    d: '马可派到东方的将领斯塔提乌斯·普里斯库斯攻入亚美尼亚，夺取了王都阿尔塔沙特，把它夷为平地，在附近另建新都，立亲罗马的阿尔沙克王族索海穆斯为亚美尼亚国王。卢基乌斯·维鲁斯因此取得“亚美尼亚征服者”的称号。他本人大部分时间留在安条克与达芙妮的别墅里享乐，战争实际上由他的将军们指挥。',
    who: ['卢基乌斯·维鲁斯'] },
  { y: 165, mo: 12, t: '焚毁塞琉西亚', p: '塞琉西亚', m: '今伊拉克巴格达南', ll: [44.52, 33.1], k: 'war', refs: ['后世文献', '考古'],
    d: '叙利亚人出身的将领阿维狄乌斯·卡西乌斯沿幼发拉底河南下，在杜拉-欧罗波斯击败帕提亚人，接着攻入美索不达米亚。底格里斯河畔的塞琉西亚本是一座希腊人的大城，开城迎接罗马人，罗马军队却借口城里有人背约，纵火焚城，据说杀死了三十万人。泰西封的王宫也被焚毁。战后奥斯若恩与杜拉-欧罗波斯归属罗马。但军队从塞琉西亚带回了一场瘟疫。',
    who: ['阿维狄乌斯·卡西乌斯', '卢基乌斯·维鲁斯', '沃洛加西斯四世'] },
  { y: 166, mo: 10, t: '安敦尼瘟疫', p: '罗马', m: '今意大利罗马', ll: [12.49, 41.88], k: 'eco', refs: ['后世文献'],
    d: '东征归来的军队在罗马举行凯旋式，也把瘟疫带到了意大利与莱茵河、多瑙河的军营。盖伦记录了病人发热、腹泻、全身出黑色的皮疹，后人多认为是天花。这场瘟疫在帝国反复流行了二十多年，估计夺走了数百万人的生命，城市与军队的人口锐减，马可·奥勒留不得不招募奴隶、角斗士与日耳曼人当兵。后人称之为“安敦尼瘟疫”。',
    who: ['马可·奥勒留', '卢基乌斯·维鲁斯', '盖伦'] },
  { y: 166, mo: 12, t: '“大秦王安敦”遣使汉朝', p: '贝勒尼刻', m: '今埃及红海省', ll: [35.48, 23.91], k: 'dip', refs: ['后汉书'],
    d: '《后汉书·西域传》说大秦国“其王常欲通使于汉，而安息欲以汉缯彩与之交市，故遮阂不得自达。至桓帝延熹九年，大秦王安敦遣使自日南徼外献象牙、犀角、玳瑁，始乃一通焉。”延熹九年就是公元 166 年，安敦就是马可·奥勒留·安敦尼，或他的前任安敦尼·庇护。从埃及红海港口出发的商船，借季风航行到印度，再经东南亚到达汉朝的日南郡，即今越南中部。这些人带来的只是南海的土产，史家也怀疑他们是借用皇帝名义的商人。这是中国史书记载的中国与罗马的第一次直接往来。',
    who: ['马可·奥勒留'] },
  { y: 170, mo: 6, t: '马科曼尼人围攻阿奎莱亚', p: '阿奎莱亚', m: '今意大利弗留利-威尼斯朱利亚大区', ll: [13.37, 45.77], k: 'war', refs: ['后世文献', '考古'],
    d: '北方的部族迁徙压迫着多瑙河边的日耳曼人。公元 167 年伦巴第人与奥比人已越过多瑙河，公元 169 年初卢基乌斯·维鲁斯在随马可北上的途中中风死去。次年马科曼尼人与夸狄人大举入侵，击溃罗马军队，翻过尤利安阿尔卑斯山，焚毁了奥皮特吉乌姆，围攻阿奎莱亚，这是二百多年来第一次有蛮族攻入意大利。同年科斯托博奇人从多瑙河下游一直劫掠到希腊，洗劫了埃琉西斯的圣地。马可为了筹措军费，在图拉真广场拍卖皇宫里的金器、珠宝与皇后的衣服。',
    who: ['马可·奥勒留', '卢基乌斯·维鲁斯', '巴洛玛里乌斯'], post: ['卢基乌斯·维鲁斯'] },
  { y: 172, mo: 6, t: '雨水奇迹', p: '夸狄人之地', m: '今斯洛伐克西南部', ll: [18.2, 48.3], k: 'war', refs: ['后世文献', '考古'],
    d: '把入侵者赶出意大利与潘诺尼亚之后，马可从卡农图姆渡过多瑙河，进攻马科曼尼人与夸狄人。据卡西乌斯·狄奥，一支罗马军队被夸狄人围困在烈日下，人马干渴将死，忽然天降大雨，士兵们仰面张口，用盾牌和头盔接雨水喝，随后冰雹与雷电落在敌人头上。异教徒说是埃及的祭司召来了雨，基督徒则说是军团里的基督徒士兵祈祷的结果。罗马城里的马可·奥勒留纪功柱上刻着这一幕：一个长着翅膀、须发淌水的雨神张开双臂。',
    who: ['马可·奥勒留'] },
  { y: 172, mo: 9, t: '格拉努亚河畔写《沉思录》', p: '格拉努亚河', m: '今斯洛伐克赫龙河下游', ll: [18.7, 47.85], k: 'cul', refs: ['马可·奥勒留·沉思录'],
    d: '马可在多瑙河边的军营里用希腊文写下给自己的笔记，后人称为《沉思录》。第一卷逐一回忆祖父、母亲、老师和养父安敦尼教给他的品德，末尾注明：**写于夸狄人之地，格拉努亚河畔||Among the Quadi at the Granua**。第二卷开头写道：**每天早上对自己说：今天我会遇到好管闲事的、忘恩负义的、傲慢的、欺诈的、嫉妒的、孤僻的人||Begin the morning by saying to thyself, I shall meet with the busybody, the ungrateful, arrogant, deceitful, envious, unsocial**，他们之所以如此，是因为不知道什么是善恶，而他们与我同出一源，我不能被他们伤害，也不能对他们发怒。这部书本不打算给别人看，却成了斯多亚哲学最有名的作品。',
    who: ['马可·奥勒留'] },
  { y: 175, mo: 4, t: '阿维狄乌斯·卡西乌斯称帝', p: '安条克', m: '今土耳其哈塔伊省安塔基亚', ll: [36.16, 36.2], k: 'war', refs: ['后世文献'],
    d: '马可与雅济吉斯人正在议和时，传来东方的阿维狄乌斯·卡西乌斯称帝的消息。卡西乌斯平定帕提亚战争有功，被授予管辖整个东方的大权，据说是听到马可已死的谣言才起兵的，也有人说是皇后小福斯蒂娜担心丈夫病重，暗中要他准备继位。埃及与叙利亚都承认了他。消息传到多瑙河，马可召集士兵讲话，说如果卡西乌斯愿意，他甘愿把帝国让给更配得上它的人，只可惜内战夺去了他宽恕的机会。',
    who: ['阿维狄乌斯·卡西乌斯', '马可·奥勒留', '小福斯蒂娜'] },
  { y: 175, mo: 7, t: '卡西乌斯之死', p: '安条克', m: '今土耳其哈塔伊省安塔基亚', ll: [36.18, 36.21], k: 'pol', refs: ['后世文献'],
    d: '称帝仅三个多月，阿维狄乌斯·卡西乌斯就被自己的一个百夫长杀死，首级送到马可面前。马可不肯看，下令埋葬，又焚毁了卡西乌斯的书信，不去追究同谋者，说他只遗憾失去了宽恕敌人的机会。他随后巡视东方，冬天皇后小福斯蒂娜死在卡帕多西亚的一个小村庄，马可把它改为城市，名叫福斯蒂诺波利斯。',
    who: ['马可·奥勒留', '阿维狄乌斯·卡西乌斯', '小福斯蒂娜'] },
  { y: 176, mo: 9, t: '马可在雅典', p: '雅典', m: '今希腊雅典', ll: [23.73, 37.98], k: 'cul', refs: ['后世文献', '考古'],
    d: '从东方回来的路上，马可在雅典接受了埃琉西斯秘仪的入会，并在雅典为柏拉图派、亚里士多德派、斯多亚派与伊壁鸠鲁派各设一个由国家支付薪俸的讲席，又设了一个修辞学的讲席。雅典由此成为整个帝国的大学城，直到六世纪被查士丁尼关闭。这年年底，马可与十五岁的儿子康茂德在罗马举行凯旋式，次年康茂德被立为共治的奥古斯都。',
    who: ['马可·奥勒留', '康茂德'] },
  { y: 177, mo: 8, t: '卢格杜努姆的殉道者', p: '卢格杜努姆', m: '今法国里昂', ll: [4.83, 45.76], k: 'cul', refs: ['后世文献'],
    d: '高卢的首府卢格杜努姆的民众指控基督徒乱伦、吃人肉，把他们赶出浴场与市场，总督逮捕了一批人。据优西比乌《教会史》保存的里昂教会书信，九十岁的主教波提努斯死在狱中，女奴布兰迪娜在竞技场里受尽酷刑，被绑在柱子上喂野兽，野兽却不碰她，最后被装进网里让公牛抛掷而死，她始终只说“我是基督徒，我们中间没有做过坏事”。马可虽然是哲学家，并没有改变图拉真定下的规矩。',
    who: ['布兰迪娜'] },
  { y: 178, mo: 8, t: '第二次马科曼尼战争', p: '卡农图姆', m: '今奥地利下奥地利州', ll: [16.91, 48.11], k: 'war', refs: ['后世文献', '考古'],
    d: '公元 175 年签订的和约没有维持多久，马可与康茂德再次北上。罗马军队连续两年击败了马科曼尼人与夸狄人，在他们的土地上驻扎了两万人，在斯洛伐克的特伦钦城堡的岩壁上，至今还刻着第二辅助军团在冬营留下的铭文，这是罗马军队到过的最北的地方之一。卡西乌斯·狄奥说马可打算把马科曼尼人与雅济吉斯人的土地设为两个新的行省。',
    who: ['马可·奥勒留', '康茂德', '庞培亚努斯'] },
  { y: 180, mo: 3, t: '马可·奥勒留之死', p: '文多博纳', m: '今奥地利维也纳', ll: [16.37, 48.21], k: 'pol', refs: ['马可·奥勒留·沉思录', '后世文献'],
    d: '五十八岁的马可在多瑙河边的军营里病倒，可能是瘟疫。他绝食，把康茂德托付给朋友们，对守夜的士兵说：“去找那升起的太阳吧，我已经要落下了。”他在《沉思录》里早就写过：**马其顿的亚历山大和他的马夫，死后归于同一个结局||Alexander the Macedonian and his groom by death were brought to the same state**。十八岁的康茂德没有按父亲的计划设立新行省，而是与马科曼尼人议和，回到罗马。马可是五贤帝中唯一有亲生儿子的人，养子继承的传统到此结束。卡西乌斯·狄奥说，罗马的历史从此由黄金时代堕入了铁与锈的时代。',
    who: ['马可·奥勒留', '康茂德', '庞培亚努斯', '盖伦'] },
];

// 人物：[名, 势力, 原名, 生卒, 简介]；跨卷人物只写名与势力，其余取 _people.js
const PEOPLE_RAW = [
  ['韦斯巴芗', 'rome', '', '', ''],
  ['提图斯', 'rome', '', '', ''],
  ['图密善', 'rome', '', '', ''],
  ['穆基阿努斯', 'rome', '', '', ''],
  ['凯里亚利斯', 'rome', 'Quintus Petillius Cerialis', '约30–83后', '韦斯巴芗的亲戚，可能是他的女婿。布狄卡起义时任第九军团长，在援救卡穆洛杜努姆的途中被击溃。公元 69 年随弗拉维军攻入罗马，次年平定巴达维人与特雷维里人的起义，在特雷维里发表了为罗马统治辩护的演说。公元 71 至 74 年任不列颠总督，征服布里甘特人，建立约克的营地。塔西佗说他作战勇猛而轻率，好几次险些丧命。'],
  ['阿古利可拉', 'rome', 'Gnaeus Julius Agricola', '40–93', '生于外高卢的福鲁姆·尤利，在马西利亚求学。青年时在苏埃托尼乌斯·保利努斯麾下参与镇压布狄卡，后统领第二十军团参加征服布里甘特。公元 77 年起任不列颠总督七年，征服威尔士北部，推进到苏格兰高地，在格劳庇乌山击败喀里多尼亚人，派舰队环航不列颠。被图密善召回后闲居，公元 93 年去世。女婿塔西佗为他写了传记。'],
  ['老普林尼', 'rome', 'Gaius Plinius Secundus', '23/24–79', '意大利北部科穆姆人，骑士出身，在日耳曼服过兵役，历任西班牙等行省的财务官，与韦斯巴芗父子交好。他勤奋得惊人，乘车、沐浴时也让人朗读做笔记，写成三十七卷的《博物志》，包罗天文、地理、动植物、矿物与艺术，是古代最大的百科全书。维苏威火山爆发时任米塞努姆舰队司令，乘船前去察看与救人，死在斯塔比伊的海滩上。'],
  ['小普林尼', 'rome', 'Gaius Plinius Caecilius Secundus', '61/62–约113', '老普林尼的外甥与养子，十七岁时在米塞努姆目睹了维苏威火山的爆发。他是著名的律师与演说家，图拉真时任执政官，发表过颂扬图拉真的颂词。他把自己的书信编成九卷出版，记下罗马上流社会的生活与维苏威的灾难；约公元 110 至 113 年任比提尼亚与本都总督，与图拉真的往来公文编为第十卷，其中有关于基督徒的著名书信。'],
  ['塔西佗', 'rome', 'Publius Cornelius Tacitus', '约56–约120', '可能出身高卢或山南高卢的骑士家庭，以雄辩著称，娶了阿古利可拉的女儿。历任大法官、执政官与亚细亚总督。图密善死后开始写作，先后写成《阿古利可拉传》《日耳曼尼亚志》《演说家对话录》，以及记述从提比略到图密善的《编年史》与《历史》，文笔简洁凝练，对专制统治与人性的洞察入木三分，被认为是罗马最伟大的史家。'],
  ['尤维纳利斯', 'rome', 'Decimus Junius Juvenalis', '约55–约130', '罗马的讽刺诗人，生平不详，据说出身意大利的阿奎农，曾因讽刺得罪权贵被流放。他的十六首讽刺诗辛辣地描写罗马城里的种种丑态，留下了“面包和竞技”“谁来看守看守者”“健全的精神寓于健全的身体”等名言。'],
  ['苏埃托尼乌斯', 'rome', 'Gaius Suetonius Tranquillus', '约69–约122后', '骑士出身的学者，小普林尼的朋友，在图拉真与哈德良时掌管皇家图书馆与皇帝的书信，得以查阅宫廷档案。约公元 122 年因对皇后萨比娜失礼被哈德良免职。所著《罗马十二帝王传》记述从恺撒到图密善十二位统治者，多载逸事与私生活，是本书数卷的主要史料。'],
  ['普鲁塔克', 'rome', 'Plutarchus', '约46–约120', '维奥蒂亚喀罗尼亚的希腊人，在雅典学习柏拉图派哲学，游历埃及与意大利，在罗马讲学，获得罗马公民权。晚年回到家乡，担任德尔斐阿波罗神庙的祭司三十年。所著《希腊罗马名人传》把希腊与罗马的名人两两对比，另有七十多篇杂论，合称《道德论集》，对文艺复兴以后的欧洲文学影响极大。'],
  ['爱比克泰德', 'rome', 'Epictetus', '约50–约135', '生于弗里吉亚的希拉波利斯，是尼禄的解放奴隶爱帕弗洛狄图斯的奴隶，跛足，据说是被主人折断的。获释后在罗马随斯多亚派哲学家穆索尼乌斯·鲁弗斯学习。约公元 93 年图密善驱逐哲学家时到希腊的尼科波利斯开办学校，终身未著书，学生阿里安记下了他的《语录》与《手册》，教人分清在我们力量之内与之外的事。'],
  ['涅尔瓦', 'rome', 'Marcus Cocceius Nerva', '30–98', '出身意大利的元老世家，历仕尼禄与弗拉维三帝，公元 65 年揭发皮索阴谋有功，曾两次任执政官。图密善遇刺当天被元老院推举为帝，时年六十六岁，在位十六个月，召回流放者，减轻赋税，设立资助意大利贫苦儿童的基金。为了安抚军队，收养了上日耳曼总督图拉真，开创了收养贤者为继承人的先例。'],
  ['图拉真', 'rome', 'Marcus Ulpius Traianus', '53–117', '生于西班牙的意大利卡，父亲是韦斯巴芗时的叙利亚总督。在莱茵河与东方统兵多年，公元 97 年任上日耳曼总督时被涅尔瓦收养，次年即位，是第一位出身行省的皇帝。两次征服达契亚，吞并纳巴泰，东征帕提亚，夺取亚美尼亚与两河流域，抵达波斯湾，帝国疆域达到极盛。在罗马修建图拉真广场、市场与纪功柱。元老院授予他“最优秀的元首”的称号，后世皇帝即位时，元老院祝愿他们“比奥古斯都更幸运，比图拉真更贤良”。'],
  ['普洛蒂娜', 'rome', 'Pompeia Plotina', '?–121/122', '图拉真的皇后，出身高卢的纳尔榜行省，以朴素、贤淑著称，据说她第一次走进皇宫时对民众说，她希望离开时还是今天这样的人。她喜好伊壁鸠鲁派哲学，与哈德良关系亲密，促成了他与图拉真甥孙女萨比娜的婚姻，图拉真临终时宣布哈德良为养子，有人怀疑是她一手安排的。'],
  ['阿波罗多洛斯', 'rome', 'Apollodorus of Damascus', '?–约130', '叙利亚大马士革出身的建筑师与工程师，随图拉真参加达契亚战争，在德罗贝塔建造了横跨多瑙河的大桥，又设计了罗马的图拉真广场、市场、浴场与纪功柱，还写过关于攻城器械的书。卡西乌斯·狄奥说他曾嘲笑哈德良画的南瓜，后来又批评哈德良设计的维纳斯与罗马神庙，被流放并处死，这个故事未必可信。'],
  ['卢西乌斯·奎图斯', 'rome', 'Lusius Quietus', '?–118', '毛里塔尼亚的毛里人首领，率领摩尔骑兵为罗马作战，在图拉真的达契亚战争中立下大功，跻身元老。东征帕提亚时攻取尼西比斯与埃德萨，又镇压美索不达米亚与犹太人的起义，被任命为犹太总督与执政官，一度被认为可能继承图拉真。哈德良即位后解除了他的兵权，次年以谋反罪被处死。'],
  ['哈德良', 'rome', 'Publius Aelius Hadrianus', '76–138', '生于罗马，家族来自西班牙的意大利卡，十岁丧父，由远亲图拉真抚养，娶了图拉真的甥孙女萨比娜。随图拉真参加达契亚与帕提亚战争，公元 117 年图拉真临终时被收养即位。他放弃了两河流域，转而巩固边防，在不列颠修筑长城，用一半的在位时间巡行帝国。他热爱希腊文化，第一个蓄须，在雅典大兴土木，重建万神殿，修建蒂布尔的别墅与自己的陵墓。晚年镇压巴尔·科赫巴起义，猜忌多疑，死后元老院一度不愿为他封神。'],
  ['萨比娜', 'rome', 'Vibia Sabina', '约83–136/137', '图拉真的外甥女马提迪娅的女儿，公元 100 年嫁给哈德良，随丈夫巡行帝国，到过埃及的门农巨像。夫妻关系冷淡，没有子女。死后被奉为神，有传言说是哈德良毒死了她。'],
  ['安提诺乌斯', 'rome', 'Antinous', '约111–130', '比提尼亚克劳狄乌波利斯的希腊少年，约公元 123 年哈德良巡行小亚细亚时遇见他，此后成为皇帝的宠爱，随他游历各地。公元 130 年十月在尼罗河上溺死。哈德良为他建立了安提诺波利斯城，把他奉为神，各地为他修建神庙、塑造雕像，在古代的肖像中数量仅次于奥古斯都与哈德良。'],
  ['尤利乌斯·塞维鲁', 'rome', 'Sextus Julius Severus', '?–?', '达尔马提亚出身的将领，被哈德良认为是最好的将军，历任默西亚与不列颠总督。巴尔·科赫巴起义时奉调到犹太，以分割、围困、断粮的办法逐个攻破起义者的据点，公元 135 年平定起义，获得凯旋的荣誉，后任叙利亚总督。'],
  ['安敦尼·庇护', 'rome', 'Titus Aurelius Fulvius Boionius Arrius Antoninus', '86–161', '家族来自外高卢的尼姆，富有而正直，曾任亚细亚总督。公元 138 年被哈德良收养，条件是收养马可与卢基乌斯·维鲁斯。即位后坚持为哈德良封神，因此得“庇护”之名。在位二十三年，从未离开意大利，国库充盈，几乎没有战争，只在不列颠修筑了安敦尼长城。临终的口令是“平静”。'],
  ['马可·奥勒留', 'rome', 'Marcus Aurelius Antoninus', '121–180', '家族来自西班牙，幼年受哈德良赏识，十七岁被安敦尼·庇护收养，娶了安敦尼的女儿小福斯蒂娜。随弗朗托学修辞，随鲁斯提库斯等人学斯多亚哲学。公元 161 年即位，与义弟卢基乌斯·维鲁斯共治。在位期间先有帕提亚战争与安敦尼瘟疫，后有十多年的马科曼尼战争，他大部分时间住在多瑙河边的军营里，用希腊文写下了《沉思录》。公元 180 年死于文多博纳或西尔米乌姆，传位给亲生儿子康茂德。'],
  ['卢基乌斯·维鲁斯', 'rome', 'Lucius Aurelius Verus', '130–169', '哈德良最初选定的继承人埃利乌斯之子，被安敦尼·庇护收养。公元 161 年马可坚持与他共治，把女儿卢基拉嫁给他。名义上统率帕提亚战争，大部分时间在安条克享乐，由阿维狄乌斯·卡西乌斯等将领取胜，取得“亚美尼亚征服者”“帕提亚征服者”的称号。公元 169 年初随马可北上时在阿尔提努姆中风死去。'],
  ['小福斯蒂娜', 'rome', 'Annia Galeria Faustina', '约130–175', '安敦尼·庇护的女儿，马可·奥勒留的皇后，生了至少十三个孩子，其中有康茂德与卢基拉。她随马可在多瑙河的军营中度过多年，被称为“军营之母”。古代史家说她不贞，并暗中鼓励阿维狄乌斯·卡西乌斯起兵，马可在《沉思录》里却称赞她温顺、深情而朴素。公元 175 年冬死于卡帕多西亚。'],
  ['康茂德', 'rome', '', '', ''],
  ['弗朗托', 'rome', 'Marcus Cornelius Fronto', '约100–约167', '阿非利加锡尔塔出身的修辞学家与律师，被认为是当时仅次于西塞罗的拉丁演说家，任过执政官，是马可·奥勒留与卢基乌斯·维鲁斯的修辞老师。他与马可的书信在十九世纪从一份重写本里被发现，信中师生亲密无间，谈天气、病痛与写作。'],
  ['盖伦', 'rome', 'Aelius Galenus', '129–约216', '帕加马富裕建筑师之子，在士麦那、科林斯与亚历山大里亚学医，回乡后为角斗士治伤。公元 162 年到罗马，以公开解剖与雄辩成名，后为马可·奥勒留与康茂德的御医，记录了安敦尼瘟疫的症状。他继承希波克拉底的体液学说，用动物解剖推论人体，著作数百种，在欧洲与伊斯兰世界的医学中统治了一千多年。'],
  ['克劳狄乌斯·托勒密', 'rome', 'Claudius Ptolemaeus', '约100–约170', '亚历山大里亚的天文学家、数学家与地理学家，与托勒密王朝没有关系。《天文学大成》（阿拉伯人称为《至大论》）以本轮与均轮解释日月五星的运行，建立了地心说的完整体系；《地理学》列出八千多个地点的经纬度，讲授地图投影。他还写过占星术的《四书》与光学、音乐的著作。'],
  ['庞培亚努斯', 'rome', '', '', ''],
  ['阿维狄乌斯·卡西乌斯', 'cassius', 'Gaius Avidius Cassius', '约130–175', '叙利亚的居鲁士城人，父亲是哈德良的秘书。以治军严厉著称，在帕提亚战争中攻取塞琉西亚与泰西封，任叙利亚总督，后被授予管辖整个东方的大权。公元 175 年听到马可已死的谣言后称帝，埃及与叙利亚响应，三个多月后被部下杀死。'],
  ['尤利乌斯·奇维利斯', 'batavi', '', '', ''],
  ['韦勒达', 'germani', 'Veleda', '?–?', '布鲁克特里人的女先知，住在利珀河边的一座塔里，不见外人。她预言了巴达维起义的胜利，罗马军团的指挥官与战船都被送给她做礼物，日耳曼人把她当作神一样尊敬。起义失败后，她可能在公元 77 年前后被罗马人俘获，被带到意大利，据说在阿尔代亚的神庙里做了仆役。'],
  ['卡尔加库斯', 'caledonii', 'Calgacus', '?–?', '据塔西佗，是格劳庇乌山之战中喀里多尼亚人的首领，“在众多首领中以勇气与出身最为出众”。塔西佗为他写的战前演说痛斥罗马人“造成一片荒漠，却称之为和平”，是古代对帝国主义最有名的控诉。他是第一个留下名字的苏格兰人，但这个名字只见于塔西佗的书中。'],
  ['德西巴卢斯', 'dacia', 'Decebalus', '?–106', '达契亚的国王，约公元 85 年即位，重新统一了达契亚诸部。公元 86 年攻入默西亚，歼灭弗斯库斯的军队，公元 89 年与图密善议和，从罗马得到补助金与工匠。图拉真两次进攻达契亚，公元 106 年王都萨尔米泽格图萨陷落，他在被俘前自杀，首级被送往罗马。图拉真纪功柱上刻着他自刎的场面。'],
  ['约瑟夫斯', 'judaea', '', '', ''],
  ['希律·亚基帕二世', 'judaea', '', '', ''],
  ['贝雷妮丝', 'judaea', 'Julia Berenice', '28–81后', '希律·亚基帕一世的女儿，亚基帕二世的姐姐，先后嫁给卡尔基斯国王与西里西亚国王，长期与弟弟同住，被罗马人传为丑闻。公元 66 年曾赤足到总督弗洛鲁斯面前求他停止屠杀。犹太战争中与提图斯相恋，公元 75 年来到罗马，住在宫中，民众反对一个东方王后，提图斯即位后把她送走。'],
  ['吉斯卡拉的约翰', 'zealots', 'John of Gischala', '?–?', '加利利吉斯卡拉人，犹太战争初期与约瑟夫斯争夺加利利的领导权，吉斯卡拉陷落前逃到耶路撒冷，联合奋锐党控制了圣殿。围城期间与西门·巴尔·吉奥拉互相攻杀，城破后在地道里饿得出来投降，被判终身监禁。'],
  ['西门·巴尔·吉奥拉', 'zealots', 'Simon bar Giora', '?–71', '格拉森人之子，犹太战争中率领一支农民与奴隶组成的队伍，许诺解放奴隶，公元 69 年被耶路撒冷人请进城对付吉斯卡拉的约翰，成为城中最强的一派领袖。城破后穿着白袍从圣殿废墟下的地道里出来投降，在韦斯巴芗与提图斯的凯旋式上被处死。'],
  ['以利亚撒·本·雅伊尔', 'zealots', 'Eleazar ben Ya\'ir', '?–73/74', '加利利人犹大的后裔，“短刀党”的首领。犹太战争初期占据马萨达，此后一直据守。罗马人攻破城墙的前夜，他劝说守军宁死不做奴隶，九百多人集体自杀。'],
  ['约哈难·本·撒该', 'judaea', 'Yohanan ben Zakkai', '?–?', '法利赛派的拉比，希勒尔的弟子。据拉比文献，耶路撒冷围城时他让弟子把自己装进棺材抬出城，向罗马统帅求得在亚夫内办学的许可。圣殿被毁后，他在亚夫内重建犹太人的公会与学院，为后世的拉比犹太教奠定了基础。'],
  ['巴尔·科赫巴', 'barkokhba', 'Simon bar Kosiba', '?–135', '本名西门·本·科西巴，公元 132 年领导犹太人反抗哈德良，被拉比阿基巴称为“星辰之子”，许多人奉他为弥赛亚，自称“以色列的亲王”。起义军铸造了自己的钱币，坚持了三年多，公元 135 年在贝塔尔战死。后来的拉比文献因起义失败称他为“巴尔·科兹巴”，意为“谎言之子”。死海边的洞穴里发现了他署名的书信。'],
  ['阿基巴', 'judaea', 'Akiva ben Joseph', '约50–约135', '最有名的犹太拉比之一，据说四十岁才开始学习，后来在亚夫内与布内布拉克讲学，弟子众多，奠定了口传律法《密西拿》的体系，坚持把《雅歌》列入正典。他支持巴尔·科赫巴，称他为弥赛亚。起义中被罗马人捕获，据说被用铁梳刮肉而死，临终念着“以色列啊，你要听”。'],
  ['拔摩的约翰', 'judaea', 'John of Patmos', '?–?', '《启示录》的作者，自称约翰，是被流放到拔摩岛的基督徒先知。教会的传统认为他就是耶稣的门徒、《约翰福音》的作者使徒约翰，晚年住在以弗所，但近代学者多认为是另一个人。'],
  ['波利卡普', 'judaea', 'Polycarp of Smyrna', '约69–155/156', '士麦那的主教，据爱任纽说是使徒约翰的弟子。约公元 155 年到罗马与主教阿尼塞图斯商讨复活节的日期，回来后在士麦那被捕，拒绝咒骂基督，被烧死。士麦那教会记述他殉道的书信是最早的殉道者传记。'],
  ['游斯丁', 'judaea', 'Justin Martyr', '约100–约165', '撒玛利亚的希腊人，研习过斯多亚派、毕达哥拉斯派与柏拉图派的哲学，后皈依基督教，仍穿哲学家的斗篷，在罗马开办学校。他写了两篇《护教辞》给安敦尼·庇护与元老院，为基督徒辩护，用希腊哲学解释基督教。约公元 165 年在罗马被斩首，被称为“殉道者游斯丁”。'],
  ['布兰迪娜', 'judaea', 'Blandina', '?–177', '卢格杜努姆的女奴，公元 177 年与主人一同作为基督徒被捕。据里昂教会的书信，她身体瘦弱，却在连续几天的酷刑与竞技场的折磨中一直坚持，鼓舞了同伴，最后被公牛抛掷而死。她后来成为里昂的主保圣人。'],
  ['沃洛加西斯一世', 'parthia', '', '', ''],
  ['奥斯罗埃斯一世', 'parthia', 'Osroes I', '?–约129', '帕提亚国王，约公元 109 年起与沃洛加西斯三世争夺王位。公元 113 年废黜亚美尼亚国王，立侄子帕尔塔马西里斯，引来图拉真的东征。泰西封陷落时出逃，女儿与王座被俘。图拉真死后回到泰西封，哈德良把他的女儿送还了他。'],
  ['帕尔塔马西里斯', 'parthia', 'Parthamasiris', '?–114', '帕提亚王族，奥斯罗埃斯一世的侄子，约公元 113 年被立为亚美尼亚国王。公元 114 年到图拉真在埃勒格亚的营中，把王冠放在皇帝脚下，图拉真却宣布亚美尼亚为罗马行省，他在离开时被杀。'],
  ['沃洛加西斯四世', 'parthia', 'Vologases IV', '?–191/192', '帕提亚国王，约公元 147 年即位。安敦尼·庇护一死就进攻亚美尼亚与叙利亚，引发了罗马与帕提亚的战争，公元 165 年塞琉西亚与泰西封被罗马人焚毁，被迫割让两河流域西北部的奥斯若恩与杜拉-欧罗波斯。'],
  ['巴洛玛里乌斯', 'marcomanni', 'Ballomar', '?–?', '马科曼尼人的国王，公元 166 或 167 年伦巴第人与奥比人越过多瑙河后，代表多瑙河北岸的十一个部族与罗马的潘诺尼亚总督谈判议和。此后马科曼尼人与夸狄人大举入侵，攻入意大利，围攻阿奎莱亚。'],
];
